import java.io.*;
import java.util.*;

public class Main {
    private static final class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();

        int[] x = new int[n];
        int[] y = new int[n];
        for (int i = 0; i < n; i++) {
            x[i] = fs.nextInt();
            y[i] = fs.nextInt();
        }

        long[] events = new long[n * n];
        int count = 0;

        for (int i = 0; i < n; i++) {
            long d = (long) x[i] * x[i] + (long) y[i] * y[i];
            events[count++] = (d << 32) | (long) (n * n + i);
        }

        for (int from = 0; from < n; from++) {
            for (int to = 0; to < n; to++) {
                if (from == to) continue;

                long dx = (long) x[from] - x[to];
                long dy = (long) y[from] - y[to];
                long d = dx * dx + dy * dy;
                int payload = from * n + to;
                events[count++] = (d << 32) | (long) payload;
            }
        }

        Arrays.sort(events);

        int[] best = new int[n];
        int[] marker = new int[n];
        int[] groupBest = new int[n];
        int[] touched = new int[n];
        int stamp = 0;
        int answer = 1;

        for (int i = 0; i < events.length; ) {
            int weight = (int) (events[i] >>> 32);
            int j = i;
            while (j < events.length && (int) (events[j] >>> 32) == weight) {
                j++;
            }

            stamp++;
            int touchedCount = 0;

            for (int k = i; k < j; k++) {
                int payload = (int) events[k];
                int node;
                int value;

                if (payload >= n * n) {
                    node = payload - n * n;
                    value = 1;
                } else {
                    int from = payload / n;
                    node = payload % n;
                    if (best[from] == 0) continue;
                    value = best[from] + 1;
                }

                if (marker[node] != stamp) {
                    marker[node] = stamp;
                    groupBest[node] = value;
                    touched[touchedCount++] = node;
                } else if (value > groupBest[node]) {
                    groupBest[node] = value;
                }
            }

            for (int k = 0; k < touchedCount; k++) {
                int node = touched[k];
                if (groupBest[node] > best[node]) {
                    best[node] = groupBest[node];
                    if (best[node] > answer) answer = best[node];
                }
            }

            i = j;
        }

        System.out.println(answer);
    }
}
